from fractions import Fraction

def polygon_area(vertices):
    # Один обход простого замкнутого контура; первую вершину не повторяем.
    double = 0
    for (x1, y1), (x2, y2) in zip(vertices, vertices[1:] + vertices[:1]):
        double += x1 * y2 - x2 * y1
    return Fraction(abs(double), 2)

P = [(0, 0), (0, 8), (10, 8), (10, 5), (4, 5), (4, 0)]
print(polygon_area(P))

def measure_vertical(commands):
    # Только целые перемещения по одной вертикальной прямой.
    y = distance = painted = 0
    down = True
    trace = set()  # k означает единичный отрезок от y=k до y=k+1
    for command, n in commands:
        if command == 'U':
            down = False
        elif command == 'D':
            down = True
        else:
            next_y = y + n if command == 'F' else y - n
            distance += n
            if down:
                painted += n
                trace.update(range(min(y, next_y), max(y, next_y)))
            y = next_y
    return distance, painted, len(trace)

commands = [('F', 8), ('B', 3), ('U', 0), ('F', 4), ('D', 0), ('B', 6)]
print(*measure_vertical(commands))
